// ---- Execução.
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "modern-syntax-golden-"));
const source_file = path.join(dir, "case_source.js");
const file = path.join(dir, "case.js");
// `vm.runInThisContext` roda como ProgramExecutable do JSC puro (o bun transpila arquivos, mas não esta string). Erro de
// compilação do programa inteiro fica engolido e `R` indefinido ("<undefined>").
fs.writeFileSync(
  file,
  `try { require("node:vm").runInThisContext(require("node:fs").readFileSync(${JSON.stringify(source_file)}, "utf8")) } catch (e) {}\n` +
    `process.stdout.write("\\u0001" + JSON.stringify(globalThis.R === undefined ? "<undefined>" : String(globalThis.R)) + "\\n");\n`,
);
const prefix = dir + "/";
const seen = new Set();
let kept = 0;
let dropped = 0;
// A matriz completa tem mais de 2200 programas; o gerador amostra por hash (sampleByHash) 1 em cada STRIDE (padrão 4, uns 570)
// para o teste ficar rápido, e `STRIDE=1` amplia a cobertura.
const STRIDE = Number(process.env.STRIDE || 4);
const allPrograms = [...new Set(programs)];
for (const source of sampleByHash(allPrograms, Math.ceil(allPrograms.length / STRIDE))) {
  if (seen.has(source)) continue;
  seen.add(source);
  fs.writeFileSync(source_file, source);
  const run = spawnSync(process.execPath, [file], { encoding: "utf8", cwd: dir, timeout: 10000 });
  const marked = (run.stdout || "").split("\n").find(line => line.startsWith("\u0001"));
  if (!marked) {
    dropped++;
    process.stderr.write("sem resultado para: " + JSON.stringify(source.slice(0, 160)) + "\n");
    continue;
  }
  const result = JSON.parse(marked.slice(1)).split("file://" + prefix).join("file:///").split(prefix).join("");
  if (result.includes(dir) || /\/home\/|\/tmp\/|\/Users\//.test(result)) {
    dropped++;
    process.stderr.write("caminho da máquina no resultado: " + JSON.stringify(source.slice(0, 160)) + "\n");
    continue;
  }
  kept++;
  emitRow(JSON.stringify(source) + "\t" + JSON.stringify(result));
}
process.stderr.write(`mantidos ${kept}, descartados ${dropped}\n`);
fs.rmSync(dir, { recursive: true, force: true });
